using Array1D = int[10];
using Array2D = float[5][3];

// Removes the first dimension: T[N] -> T
using Result1D = std::remove_extent_t<Array1D>;
// Result1D is int

// Removes the first dimension: T[N][M] -> T[M]
using Result2D = std::remove_extent_t<Array2D>;
// Result2D is float[3]

// Non-array types remain unchanged
using ResultNonArray = std::remove_extent_t<int*>;
// ResultNonArray is int*
